def compute(vars):
    values = [vars["v1"], vars["v2"]]
    exceeds_threshold = [value > 200 for value in values]
    count = sum(exceeds_threshold)
    return {
        "value": count,
        "trace": {
            "threshold": 200,
            "values": values,
            "exceeds_threshold": exceeds_threshold,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "years"
            }
        }
    }
